package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.Closeable;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class MappingIterator_hasNextValue_TriageGen1Test {

    /**
     * Helper to inject private fields into MappingIterator via reflection
     * since we cannot easily instantiate it with a custom parser via public constructors.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testHasNextValue_ParserIsNull() throws Exception {
        MappingIterator<Object> iterator = mock(MappingIterator.class);
        // We use a spy or real object if possible, but given the constraints, 
        // we must simulate the internal state. 
        // Since we cannot easily instantiate MappingIterator without a parser, 
        // we'll assume a mock-based approach for the object under test if it were a real instance.
        // However, for true coverage of the logic, we need a real instance with reflected fields.

        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        setPrivateField(realIterator, "_parser", null);

        assertFalse(realIterator.hasNextValue());
    }

    @Test
    public void testHasNextValue_HasNextCheckedTrue() throws Exception {
        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        JsonParser mockParser = mock(JsonParser.class);

        setPrivateField(realIterator, "_parser", mockParser);
        setPrivateField(realIterator, "_hasNextChecked", true);

        assertTrue(realIterator.hasNextValue());
        verifyNoInteractions(mockParser);
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenNotNull() throws Exception {
        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        JsonParser mockParser = mock(JsonParser.class);

        setPrivateField(realIterator, "_parser", mockParser);
        setPrivateField(realIterator, "_hasNextChecked", false);
        when(mockParser.getCurrentToken()).thenReturn(JsonToken.START_OBJECT);

        assertTrue(realIterator.hasNextValue());
        verify(mockParser).getCurrentToken();

        // Verify _hasNextChecked is now true
        Field checkedField = realIterator.getClass().getDeclaredField("_hasNextChecked");
        checkedField.setAccessible(true);
        assertTrue((Boolean) checkedField.get(realIterator));
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_ThenNextTokenNotNull() throws Exception {
        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        JsonParser mockParser = mock(JsonParser.class);

        setPrivateField(realIterator, "_parser", mockParser);
        setPrivateField(realIterator, "_hasNextChecked", false);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        assertTrue(realIterator.hasNextValue());
        verify(mockParser).nextToken();
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_ThenNextTokenIsNull() throws Exception {
        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        JsonParser mockParser = mock(JsonParser.class);

        setPrivateField(realIterator, "_parser", mockParser);
        setPrivateField(realIterator, "_hasNextChecked", false);
        setPrivateField(realIterator, "_closeParser", false);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(null);

        assertFalse(realIterator.hasNextValue());

        // Verify parser is set to null
        Field parserField = realIterator.getClass().getDeclaredField("_parser");
        parserField.setAccessible(true);
        assertNull(parserField.get(realIterator));
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_ThenNextTokenEndArray() throws Exception {
        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        JsonParser mockParser = mock(JsonParser.class);

        setPrivateField(realIterator, "_parser", mockParser);
        setPrivateField(realIterator, "_hasNextChecked", false);
        setPrivateField(realIterator, "_closeParser", false);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertFalse(realIterator.hasNextValue());

        Field parserField = realIterator.getClass().getDeclaredField("_parser");
        parserField.setAccessible(true);
        assertNull(parserField.get(realIterator));
    }

    @Test
    public void testHasNextValue_FirstCheck_TokenIsNull_ThenNextTokenEndArray_WithCloseParser() throws Exception {
        MappingIterator<Object> realIterator = mock(MappingIterator.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));
        JsonParser mockParser = mock(JsonParser.class);

        setPrivateField(realIterator, "_parser", mockParser);
        setPrivateField(realIterator, "_hasNextChecked", false);
        setPrivateField(realIterator, "_closeParser", true);

        when(mockParser.getCurrentToken()).thenReturn(null);
        when(mockParser.nextToken()).thenReturn(JsonToken.END_ARRAY);

        assertFalse(realIterator.hasNextValue());

        verify(mockParser).close();

        Field parserField = realIterator.getClass().getDeclaredField("_parser");
        parserField.setAccessible(true);
        assertNull(parserField.get(realIterator));
    }
}
